  "project_id": "49e0b2454e974277b0db",
  "name": "create_private_user_files_storage",
  "query": "insert into storage.buckets (id, name, public)
values ('user-files', 'user-files', false)
on conflict (id) do update set name = excluded.name, public = false;

-- Keep every object in this private bucket scoped to the authenticated user's
-- top-level folder: <auth.uid()>/<filename>.
drop policy if exists "user_files_select_own" on storage.objects;
drop policy if exists "user_files_insert_own" on storage.objects;
drop policy if exists "user_files_update_own" on storage.objects;
drop policy if exists "user_files_delete_own" on storage.objects;

create policy "user_files_select_own"
on storage.objects
for select
to authenticated
using (
  bucket_id = 'user-files'
  and (storage.foldername(name))[1] = (select auth.uid()::text)
);

create policy "user_files_insert_own"
on storage.objects
for insert
to authenticated
with check (
  bucket_id = 'user-files'
  and (storage.foldername(name))[1] = (select auth.uid()::text)
);

create policy "user_files_update_own"
on storage.objects
for update
to authenticated
using (
  bucket_id = 'user-files'
  and (storage.foldername(name))[1] = (select auth.uid()::text)
)
with check (
  bucket_id = 'user-files'
  and (storage.foldername(name))[1] = (select auth.uid()::text)
);

create policy "user_files_delete_own"
on storage.objects
for delete
to authenticated
using (
  bucket_id = 'user-files'
  and (storage.foldername(name))[1] = (select auth.uid()::text)
);"
}

